const s = $('Ambil Detail').first().json;
const urut = $('When Executed by Another Workflow').first().json.no_surat;
if (!urut) throw new Error('Nomor urut kosong.');

const inputTgl = $('When Executed by Another Workflow').first().json.tanggal_surat;
const tglSurat = inputTgl ? new Date(inputTgl + 'T00:00:00') : new Date();

const th = new Date().getFullYear();
const today = new Date();
const bulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const tahun_pelajaran = today.getMonth() >= 6 ? `${th}/${th+1}` : `${th-1}/${th}`;

function formatTanggalID(t) {
  if (!t) return '';
  const bulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli',
    'Agustus','September','Oktober','November','Desember'];
  const d = new Date(t);
  if (isNaN(d)) return t;                 // kalau tak terbaca, kembalikan apa adanya
  return `${d.getDate()} ${bulan[d.getMonth()]} ${d.getFullYear()}`;
}

