const data = $('Siapkan Data').first().json;
let tpl = $input.first().json.html;
if (!tpl || typeof tpl !== 'string') throw new Error('Template kosong.');
for (const k of Object.keys(data)) {
  tpl = tpl.split('{{' + k + '}}').join(data[k] ?? '');
}
return [{
  json: {},
  binary: { index_html: { data: Buffer.from(tpl).toString('base64'), mimeType: 'text/html', fileName: 'index.html' } }
}];

