const pdf = $('Gotenberg').first().binary;   // ganti dengan nama asli node Gotenberg Anda
const s = $('Siapkan Data').first().json;

// bersihkan nama siswa agar aman jadi nama file
const namaBersih = (s.nama_siswa || 'Siswa')
  .replace(/[\/\\:*?"<>|]/g, '')   // buang karakter terlarang di nama file
  .trim();

// ganti fileName pada binary
const key = Object.keys(pdf)[0];              // nama field binary (mis. 'data')
pdf[key] = { ...pdf[key], fileName: `Surat Keterangan Aktif - ${namaBersih}.pdf` };

return [{ json: s, binary: pdf }];
